        rotate([90, 0, 0]) {
            // Shaft hole through entire plate
            cylinder(d=m3_shaft_dia, h=wall_plate_thickness + 0.02);
            // Countersink for flat head screw (from back/wall side)
            // The countersink is on the front face (screw goes from front)
            // Actually, screw goes through plate into wall, so countersink on front
            translate([0, 0, wall_plate_thickness - m3_head_depth])
                cylinder(d1=m3_shaft_dia, d2=m3_head_dia, h=m3_head_depth + 0.01);
