        // Tip of arm before curve
        translate([-(hook_width/2), hook_reach - hook_curve_radius, 0])
            cube([hook_width, 0.01, 8]);
    }
}

module hook_curve() {
    // The curved hook portion
    arm_start_z = -wall_plate_height/2 + 8;

    translate([0, wall_plate_thickness + hook_reach - hook_curve_radius, arm_start_z + 4])
    rotate([0, 90, 0])
    translate([0, 0, -hook_width/2])
