{'content': "// Towel Hook - Wall mounted with single M3 flat head (countersunk) screw
// Designed for 3D printing - robust enough for a large towel
// Print orientation: flat side (wall plate) on print bed

$fn = 100;

// === Wall Plate Parameters ===
plate_w = 32;           // Width of wall plate
plate_h = 45;           // Height of wall plate
plate_t = 5;            // Thickness of wall plate
plate_corner_r = 4;     // Corner rounding radius

// === Hook Parameters ===
hook_w = 22;            // Width of the hook
hook_arm_len = 30;      // Length of arm extending from plate
hook_arm_t = 8;         // Thickness of arm (vertical)
hook_curve_r = 14;      // Inner radius of hook curve
hook_bar_dia = 8;       // Diameter of the hook bar (cross section)
hook_opening_angle = 60; // Opening angle (how much of curve is open at top)

// === M3 Countersunk Screw ===
m3_clear = 3.4;         // M3 clearance diameter
m3_head_d = 6.8;        // Countersunk head outer diameter
m3_cs_depth = 2.0;      // Countersink depth

// === Gusset/reinforcement ===
gusset_h = 20;          // Height of triangular gusset

// Screw hole position (upper portion of plate for leverage)
screw_z = plate_h/2 - 12;

// Hook arm starts at bottom of plate
arm_z = -plate_h/2 + hook_arm_t/2 + 3;

// --- Modules ---

module rounded_rect(w, h, r) {
    // 2D rounded rectangle centered
    offset(r=r) square([w - 2*r, h - 2*r], center=true);
}

module wall_plate() {
    translate([0, plate_t/2, 0])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                rounded_rect(plate_w, plate_h, plate_corner_r);
}

module screw_hole() {
    translate([0, 0, screw_z]) {
        rotate([90, 0, 0]) {
            // Through hole
            translate([0, 0, -plate_t/2 - 1])
                cylinder(d=m3_clear, h=plate_t + 2);
            // Countersink on the front face
            translate([0, 0, plate_t/2 - m3_cs_depth])
                cylinder(d1=m3_clear, d2=m3_head_d, h=m3_cs_depth + 0.01);
        }
    }
}

module hook_arm() {
    // Rectangular arm extending from wall plate
    translate([0, plate_t + hook_arm_len/2, arm_z])
        cube([hook_w, hook_arm_len, hook_arm_t], center=true);
}

module hook_curve_section() {
    // The J-shaped hook at the end of the arm
    // Center of the curve arc
    cx = 0;
    cy = plate_t + hook_arm_len;
    cz = arm_z + hook_curve_r + hook_arm_t/2;

    translate([cx, cy, cz])
        rotate([0, 90, 0])
            translate([0, 0, -hook_w/2])
                linear_extrude(height=hook_w) {
                    difference() {
                        circle(r=hook_curve_r + hook_bar_dia/2);
                        circle(r=hook_curve_r - hook_bar_dia/2);
                        // Remove top opening
                        rotate([0, 0, 90 - hook_opening_angle])
                            translate([0, 0])
                                square([50, 50]);
                        // Remove right side to keep only the hook shape
                        // We want the curve to go from bottom, around left, and partway up
                        // Keep from 90+opening_angle to 360-ε
                        // Actually let's think about this differently:
                        // At angle 0 = right = toward wall (top of hook in Z)
                        // We want to keep the curve going:
                        //   from the bottom of the arm (angle 180° = away from wall, downward)
                        //   around through 270° (pointing down toward -Y)
                        //   and up to some angle past 360/0

                        // Remove a wedge from the top to create the hook opening
                        // The arm connects at the top (angle 0), and hook goes down and around
                        // Opening should be roughly at angle (hook_opening_angle) from top
                    }
                }
}

// Let me redo the hook with a cleaner parametric approach
module hook_profile_2d() {
    // Create the hook cross-section as a 2D profile
    // The hook bar follows an arc
    bar_r = hook_bar_dia / 2;

    // Arc from 0 (right/top) going clockwise: 0 -> -90 -> -180 -> -(180+extra)
    // In OpenSCAD angles are CCW, so we go from start_angle to end_angle
    start_angle = hook_opening_angle;  // Opening near top
    end_angle = 360;                   // Full sweep minus opening

    steps = 60;
    step_angle = (end_angle - start_angle) / steps;

    for (i = [0:steps-1]) {
        a1 = start_angle + i * step_angle;
        a2 = start_angle + (i+1) * step_angle;
        hull() {
            translate([hook_curve_r * cos(a1), hook_curve_r * sin(a1)])
                circle(r=bar_r);
            translate([hook_curve_r * cos(a2), hook_curve_r * sin(a2)])
                circle(r=bar_r);
        }
    }
}

module hook_curved() {
    cx = 0;
    cy = plate_t + hook_arm_len;
    cz = arm_z - hook_bar_dia/2 + hook_arm_t/2;

    translate([0, cy, cz + hook_curve_r])
        rotate([0, 90, 0])
            translate([0, 0, -hook_w/2])
                linear_extrude(height=hook_w)
                    hook_profile_2d();
}

module gusset() {
    // Triangular gusset between wall plate and arm for strength
    gw = hook_w;

    translate([-gw/2, 0, 0])
    linear_extrude(height=gw) {
        polygon([
            [plate_t, arm_z + hook_arm_t/2],          // Top of arm at wall
            [plate_t, arm_z + hook_arm_t/2 + gusset_h], // Up along wall
            [plate_t + gusset_h * 0.6, arm_z + hook_arm_t/2]  // Along arm
        ]);
    }

    // Bottom fillet too
    translate([-gw/2, 0, 0])
    linear_extrude(height=gw) {
        polygon([
            [plate_t, arm_z - hook_arm_t/2],           // Bottom of arm at wall
            [plate_t, arm_z - hook_arm_t/2 - 5],       // Down along wall
            [plate_t + 5, arm_z - hook_arm_t/2]        // Along arm
        ]);
    }
}

// Swap Y and Z in the gusset - let me redo this properly
// The coordinate system:
// X = left-right
// Y = depth (0=wall, positive=away from wall)
// Z = up-down

module gusset_v2() {
    gw = hook_w;

    // Upper triangular gusset (connects top of arm to wall plate above)
    translate([-gw/2, plate_t, arm_z + hook_arm_t/2])
        rotate([0, 90, 0])
            rotate([0, 0, -90])
                linear_extrude(height=gw)
                    polygon([
                        [0, 0],
                        [0, gusset_h],
                        [gusset_h * 0.7, 0]
                    ]);
}

module towel_hook() {
    difference() {
        union() {
            wall_plate();
            hook_arm();
            hook_curved();
            gusset_v2();
        }
        screw_hole();
    }
}

towel_hook();
"}

{'content': '// Towel Hook - Wall mounted with single M3 flat head (countersunk) screw
// Designed for 3D printing - robust enough for a large towel
// Print orientation: wall plate flat on print bed

$fn = 100;

// === Wall Plate Parameters ===
plate_w = 35;           // Width of wall plate
plate_h = 50;           // Height of wall plate  
plate_t = 5;            // Thickness of wall plate
plate_corner_r = 4;     // Corner rounding radius

// === Hook Parameters ===
hook_w = 24;            // Width of the hook body
hook_bar_r = 4.5;       // Radius of hook bar cross-section (9mm diameter bar)
hook_reach = 32;        // How far hook extends from wall
hook_inner_r = 13;      // Inner radius of the hook curve
hook_tip_upturn = 8;    // How far the tip turns back up (anti-slip)

// === M3 Countersunk Screw ===
m3_clear = 3.4;
m3_head_d = 6.8;
m3_cs_depth = 2.0;

// Derived
screw_z = plate_h/2 - 12;  // Screw in upper portion
arm_bottom_z = -plate_h/2 + 5;  // Bottom of arm near plate bottom

// Create 2D side profile of the entire hook, then extrude
module hook_side_profile() {
    arm_t = hook_bar_r * 2;  // Arm thickness = bar diameter

    // Arm: from wall plate to start of curve
    // Arm goes from Y=0 (wall plate surface) to Y=hook_reach-hook_inner_r
    arm_y_end = hook_reach - hook_inner_r;

    // Arm rectangle
    translate([0, arm_bottom_z + hook_bar_r])
        square([arm_y_end, arm_t], center=false);

    // Hook curve - center at (arm_y_end, arm_bottom_z + hook_bar_r + hook_inner_r + hook_bar_r)
    curve_cx = arm_y_end;
    curve_cz = arm_bottom_z + hook_bar_r + hook_inner_r + hook_bar_r;

    // Generate curve from -90 to about 150 degrees (sweeping around)
    // -90 = bottom (connects to arm), going CCW through 0 (right/outward), 
    // 90 (top), 180 (left/toward wall)

    steps = 60;
    start_a = -90;
    end_a = 90 + 50;  // Go past top and curve back toward wall

    for (i = [0:steps-1]) {
        a1 = start_a + i * (end_a - start_a) / steps;
        a2 = start_a + (i+1) * (end_a - start_a) / steps;
        hull() {
            translate([curve_cx + hook_inner_r * cos(a1), curve_cz + hook_inner_r * sin(a1)])
                circle(r=hook_bar_r);
            translate([curve_cx + hook_inner_r * cos(a2), curve_cz + hook_inner_r * sin(a2)])
                circle(r=hook_bar_r);
        }
    }
}

// Gusset profile (triangular reinforcement)
module gusset_profile() {
    arm_t = hook_bar_r * 2;
    gusset_h = 22;  // Height of gusset along wall
    gusset_l = 18;  // Length of gusset along arm

    // Triangle from top of arm going up along wall and along arm
    polygon([
        [0, arm_bottom_z + arm_t],           // Top of arm at wall junction
        [0, arm_bottom_z + arm_t + gusset_h], // Up along wall
        [gusset_l, arm_bottom_z + arm_t]       // Along arm
    ]);
}

module wall_plate() {
    // Rounded rectangle, centered in XZ plane, extending in +Y
    translate([0, plate_t/2, 0])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                offset(r=plate_corner_r)
                    square([plate_w - 2*plate_corner_r, plate_h - 2*plate_corner_r], center=true);
}

module screw_hole() {
    translate([0, plate_t + 1, screw_z])
        rotate([90, 0, 0]) {
            // Through hole
            cylinder(d=m3_clear, h=plate_t + 2);
            // Countersink on front face (Y=plate_t side)
            cylinder(d1=m3_head_d, d2=m3_clear, h=m3_cs_depth + 0.01);
        }
}

module hook_body() {
    // Extrude the side profile along X axis
    translate([-hook_w/2, 0, 0])
        rotate([0, 90, 0])
            rotate([0, 0, 90])
                linear_extrude(height=hook_w)
                    hook_side_profile();
}

module gusset() {
    translate([-hook_w/2, 0, 0])
        rotate([0, 90, 0])
            rotate([0, 0, 90])
                linear_extrude(height=hook_w)
                    gusset_profile();
}

module towel_hook() {
    difference() {
        union() {
            wall_plate();
            // Offset hook body by plate thickness
            translate([0, plate_t, 0]) {
                hook_body();
                gusset();
            }
        }
        screw_hole();
    }
}

towel_hook();
'}

{'content': '// Towel Hook - Wall mounted with single M3 flat head (countersunk) screw
// Designed for 3D printing - robust enough for a large towel
// Print orientation: wall plate flat on print bed (Y=0 face down)

$fn = 100;

// === Wall Plate Parameters ===
plate_w = 36;           // Width of wall plate
plate_h = 50;           // Height of wall plate  
plate_t = 5;            // Thickness of wall plate
plate_corner_r = 5;     // Corner rounding radius

// === Hook Parameters ===
hook_w = 24;            // Width of the hook body
hook_bar_r = 5;         // Radius of hook bar cross-section (10mm thick bar)
hook_reach = 35;        // How far hook extends from wall surface
hook_inner_r = 14;      // Inner radius of the hook curve

// === M3 Countersunk Screw ===
m3_clear = 3.4;         // M3 clearance hole
m3_head_d = 7.0;        // Countersunk head diameter (slightly generous)
m3_cs_depth = 2.0;      // Countersink depth

// === Derived dimensions ===
screw_z = plate_h/2 - 13;     // Screw in upper portion for good leverage
arm_bottom_z = -plate_h/2 + 6; // Bottom of arm near plate bottom
arm_t = hook_bar_r * 2;        // Arm thickness = bar diameter

// === 2D Side profile of hook (in YZ plane) ===
module hook_side_profile() {
    arm_y_end = hook_reach - hook_inner_r;

    // Arm: horizontal bar from wall plate to curve start
    // Slight downward slope for aesthetics and drainage
    hull() {
        translate([0, arm_bottom_z + hook_bar_r])
            circle(r=hook_bar_r);
        translate([arm_y_end, arm_bottom_z + hook_bar_r])
            circle(r=hook_bar_r);
    }

    // Hook curve
    curve_cx = arm_y_end;
    curve_cz = arm_bottom_z + hook_bar_r + hook_inner_r + hook_bar_r;

    // Sweep from -90° (bottom, where arm meets) CCW to ~150° 
    // This creates a J-hook that curves up past the opening
    steps = 60;
    start_a = -90;
    end_a = 140;  // Generous upturn to prevent towel sliding off

    for (i = [0:steps-1]) {
        a1 = start_a + i * (end_a - start_a) / steps;
        a2 = start_a + (i+1) * (end_a - start_a) / steps;
        hull() {
            translate([curve_cx + hook_inner_r * cos(a1), 
                       curve_cz + hook_inner_r * sin(a1)])
                circle(r=hook_bar_r);
            translate([curve_cx + hook_inner_r * cos(a2), 
                       curve_cz + hook_inner_r * sin(a2)])
                circle(r=hook_bar_r);
        }
    }
}

// Gusset profile - triangular reinforcement
module gusset_profile() {
    gusset_h = 24;   // Height along wall
    gusset_l = 20;   // Length along arm

    // Smooth curved gusset using hull of circles
    hull() {
        translate([0, arm_bottom_z + arm_t + 0.5])
            circle(r=0.5);
        translate([0, arm_bottom_z + arm_t + gusset_h])
            circle(r=0.5);
    }

    // Filled triangle between wall, gusset top, and arm
    polygon([
        [0, arm_bottom_z + arm_t],
        [0, arm_bottom_z + arm_t + gusset_h],
        [gusset_l, arm_bottom_z + arm_t]
    ]);
}

// === Assembly ===

module wall_plate() {
    translate([0, plate_t/2, 0])
        rotate([90, 0, 0])
            linear_extrude(height=plate_t, center=true)
                offset(r=plate_corner_r)
                    square([plate_w - 2*plate_corner_r, plate_h - 2*plate_corner_r], center=true);
}

module screw_hole() {
    // Screw enters from front (high Y), goes through plate into wall
    translate([0, plate_t + 0.01, screw_z])
        rotate([90, 0, 0]) {
            // Through hole
            cylinder(d=m3_clear, h=plate_t + 0.02);
            // Countersink on front face
            cylinder(d1=m3_head_d, d2=m3_clear, h=m3_cs_depth + 0.01);
        }
}

module hook_body() {
    translate([-hook_w/2, 0, 0])
        rotate([0, 90, 0])
            rotate([0, 0, 90])
                linear_extrude(height=hook_w)
                    hook_side_profile();
}

module gusset() {
    translate([-hook_w/2, 0, 0])
        rotate([0, 90, 0])
            rotate([0, 0, 90])
                linear_extrude(height=hook_w)
                    gusset_profile();
}

// Smooth transition from narrow hook body to wider plate
module transition_wings() {
    // Left and right wing fillets
    wing_h = arm_t + 24 + arm_t; // Height of transition area
    wing_start_z = arm_bottom_z;

    for (side = [-1, 1]) {
        hull() {
            // At hook body edge
            translate([side * hook_w/2, plate_t, arm_bottom_z])
                cube([0.01, 3, arm_t + 24]);
            // At plate edge
            translate([side * (plate_w/2 - plate_corner_r), plate_t/2, arm_bottom_z])
                cube([0.01, plate_t/2, arm_t + 24]);
        }
    }
}

module towel_hook() {
    difference() {
        union() {
            wall_plate();
            translate([0, plate_t, 0]) {
                hook_body();
                gusset();
            }
            transition_wings();
        }
        screw_hole();
    }
}

towel_hook();
'}

